384	    if (id === '' || id.includes('/')) throw new HttpError(404, 'not found');
385	    if (method !== 'DELETE') throw notAllowed();
386	    deleteBooking(id);
387	    res.writeHead(204);
388	    return res.end();
389	  }
390	  if (pathname === '/') {
391	    if (method !== 'GET') throw notAllowed();
392	    return sendText(res, 'text/html; charset=utf-8', PAGE);
393	  }
394	  if (pathname === '/app.js') {
395	    if (method !== 'GET') throw notAllowed();
396	    return sendText(res, 'text/javascript; charset=utf-8', SCRIPT);
397	  }
398	  throw new HttpError(404, 'not found');
399	}
400	
401	const server = http.createServer((req, res) => {
402	  handle(req, res).catch((err) => {
403	    if (res.headersSent || res.destroyed) return;
404	    if (err instanceof HttpError) sendJson(res, err.status, { error: err.message });
405	    else sendJson(res, 500, { error: 'internal error' });
406	  });
407	});
