r = await run({ PORT: '65536' }, tmp); check('port 65536', r.code === 1);
r = await run({ PORT: ' 80' }, tmp); check('port space', r.code === 1);
r = await run({ PORT: '0x10' }, tmp); check('port hex', r.code === 1);
r = await run({ PORT: '1e3' }, tmp); check('port 1e3', r.code === 1);
r = await run({ PORT: '0', DATA_FILE: 'sub' }, tmp, false);
fs.mkdirSync(path.join(tmp, 'dir'));
r = await run({ PORT: '0', DATA_FILE: 'dir' }, tmp); check('dir datafile', r.code === 1 && r.err === 'cannot read data file dir\n', JSON.stringify(r));
