import { spawn } from 'node:child_process';
import net from 'node:net';
import fs from 'node:fs';
import path from 'node:path';

const sol = process.argv[2];
const serverPath = path.resolve(sol, 'server.mjs');
const results = [];
function check(name, ok, info = '') { results.push(`${ok ? 'PASS' : 'FAIL'} ${name} ${ok ? '' : info}`); }

function run(env, cwd, waitListen = true) {
  return new Promise((resolve) => {
    const p = spawn(process.execPath, [serverPath], { cwd, env: { PATH: process.env.PATH, ...env } });
    let out = '', err = '';
    p.stdout.on('data', (d) => { out += d; const m = /listening on http:\/\/127\.0\.0\.1:(\d+)\n/.exec(out); if (waitListen && m) resolve({ p, port: Number(m[1]), get out() { return out; }, get err() { return err; } }); });
    p.stderr.on('data', (d) => { err += d; });
    p.on('exit', (code) => resolve({ code, out, err }));
  });
}

function raw(port, text) {
  return new Promise((resolve) => {
    const s = net.connect(port, '127.0.0.1');
    let buf = '';
    s.on('data', (d) => { buf += d; });
    s.on('end', () => resolve(buf));
    s.on('close', () => resolve(buf));
    s.on('error', (e) => resolve('ERR ' + e.message + buf));
    s.write(text);
    setTimeout(() => { resolve(buf); s.destroy(); }, 800);
  });
}

